	AND waitlist_signups.subject_id = sqlc.arg(subject_id)
	AND waitlist_signups.id > COALESCE(sqlc.narg(page_cursor), '')
ORDER BY waitlist_signups.id ASC
LIMIT COALESCE(sqlc.narg(result_limit), 50);

-- name: ListSignupsForSubjectDescending :many
SELECT
	waitlist_signups.id,
	waitlist_signups.scope,
	waitlist_signups.waitlist_id,
	waitlist_signups.contact,
	waitlist_signups.contact_digest,
	waitlist_signups.subject_type,
	waitlist_signups.subject_id,
	waitlist_signups.notes,
	waitlist_signups.status,
	waitlist_signups.status_changed_at,
	waitlist_signups.created_at,
	waitlist_signups.last_updated_at,
	waitlist_signups.archived_at,
	(
		SELECT COUNT(waitlist_signups.id)
		FROM waitlist_signups
		WHERE waitlist_signups.created_at > COALESCE(sqlc.narg(created_after), (SELECT CURRENT_TIMESTAMP - '999 years'::INTERVAL))
			AND waitlist_signups.created_at < COALESCE(sqlc.narg(created_before), (SELECT CURRENT_TIMESTAMP + '999 years'::INTERVAL))
			AND (
				waitlist_signups.last_updated_at IS NULL
				OR waitlist_signups.last_updated_at > COALESCE(sqlc.narg(updated_after), (SELECT CURRENT_TIMESTAMP - '999 years'::INTERVAL))
			)
			AND (
				waitlist_signups.last_updated_at IS NULL
				OR waitlist_signups.last_updated_at < COALESCE(sqlc.narg(updated_before), (SELECT CURRENT_TIMESTAMP + '999 years'::INTERVAL))
			)
			AND (COALESCE(sqlc.narg(include_archived), false)::boolean OR waitlist_signups.archived_at IS NULL)
			AND waitlist_signups.scope = sqlc.arg(scope)
			AND waitlist_signups.subject_type = sqlc.arg(subject_type)
			AND waitlist_signups.subject_id = sqlc.arg(subject_id)
	) AS filtered_count,
	(
		SELECT COUNT(waitlist_signups.id)
		FROM waitlist_signups
		WHERE (COALESCE(sqlc.narg(include_archived), false)::boolean OR waitlist_signups.archived_at IS NULL)
			AND waitlist_signups.scope = sqlc.arg(scope)
			AND waitlist_signups.subject_type = sqlc.arg(subject_type)
			AND waitlist_signups.subject_id = sqlc.arg(subject_id)
	) AS total_count
FROM waitlist_signups
WHERE waitlist_signups.created_at > COALESCE(sqlc.narg(created_after), (SELECT CURRENT_TIMESTAMP - '999 years'::INTERVAL))
	AND waitlist_signups.created_at < COALESCE(sqlc.narg(created_before), (SELECT CURRENT_TIMESTAMP + '999 years'::INTERVAL))
	AND (
		waitlist_signups.last_updated_at IS NULL
		OR waitlist_signups.last_updated_at > COALESCE(sqlc.narg(updated_after), (SELECT CURRENT_TIMESTAMP - '999 years'::INTERVAL))
	)
	AND (
		waitlist_signups.last_updated_at IS NULL
		OR waitlist_signups.last_updated_at < COALESCE(sqlc.narg(updated_before), (SELECT CURRENT_TIMESTAMP + '999 years'::INTERVAL))
	)
	AND (COALESCE(sqlc.narg(include_archived), false)::boolean OR waitlist_signups.archived_at IS NULL)
	AND waitlist_signups.scope = sqlc.arg(scope)
	AND waitlist_signups.subject_type = sqlc.arg(subject_type)
	AND waitlist_signups.subject_id = sqlc.arg(subject_id)
	AND (waitlist_signups.id <= COALESCE(sqlc.narg(page_cursor), waitlist_signups.id) AND waitlist_signups.id <> COALESCE(sqlc.narg(page_cursor), ''))
ORDER BY waitlist_signups.id DESC
LIMIT COALESCE(sqlc.narg(result_limit), 50);

-- name: InsertSignup :exec
INSERT INTO waitlist_signups (
	id,
	scope,
	waitlist_id,
	contact,
	contact_digest,
	subject_type,
	subject_id,
	notes,
	status,
	status_changed_at
) VALUES (
	sqlc.arg(id),
	sqlc.arg(scope),
	sqlc.arg(waitlist_id),
	sqlc.arg(contact),
	sqlc.arg(contact_digest),
	sqlc.arg(subject_type),
	sqlc.arg(subject_id),
	sqlc.arg(notes),
	sqlc.arg(status),
	sqlc.narg(status_changed_at)
);

-- name: UpdateSignupNotes :execrows
UPDATE waitlist_signups SET
	notes = sqlc.arg(notes),
	last_updated_at = CURRENT_TIMESTAMP
WHERE archived_at IS NULL
	AND id = sqlc.arg(id)
	AND scope = sqlc.arg(scope)
	AND waitlist_id = sqlc.arg(waitlist_id);

-- name: TransitionSignup :execrows
UPDATE waitlist_signups SET
	status = sqlc.arg(status),
	status_changed_at = sqlc.narg(status_changed_at),
	last_updated_at = CURRENT_TIMESTAMP
WHERE archived_at IS NULL
	AND id = sqlc.arg(id)
	AND scope = sqlc.arg(scope)
	AND waitlist_id = sqlc.arg(waitlist_id)
	AND status = sqlc.arg(expected_status);

-- name: WithdrawSignup :execrows
UPDATE waitlist_signups SET
	contact = sqlc.arg(contact),
	subject_type = sqlc.arg(subject_type),
	subject_id = sqlc.arg(subject_id),
	notes = sqlc.arg(notes),
	status = sqlc.arg(status),
	status_changed_at = sqlc.narg(status_changed_at),
	last_updated_at = CURRENT_TIMESTAMP
WHERE archived_at IS NULL
	AND id = sqlc.arg(id)
	AND scope = sqlc.arg(scope)
	AND waitlist_id = sqlc.arg(waitlist_id)
	AND status <> sqlc.arg(expected_status);

-- name: ArchiveSignup :execrows
UPDATE waitlist_signups SET
	archived_at = CURRENT_TIMESTAMP
WHERE archived_at IS NULL
	AND id = sqlc.arg(id)
	AND scope = sqlc.arg(scope)
	AND waitlist_id = sqlc.arg(waitlist_id);

-- name: WithdrawSignupsForSubject :execrows
UPDATE waitlist_signups SET
	contact = sqlc.arg(contact),
	subject_type = sqlc.arg(subject_type),
	subject_id = sqlc.arg(subject_id),
	notes = sqlc.arg(notes),
	status = sqlc.arg(status),
	status_changed_at = sqlc.narg(status_changed_at),
	last_updated_at = CURRENT_TIMESTAMP
WHERE scope = sqlc.arg(scope)
	AND subject_type = sqlc.arg(erased_subject_type)
	AND subject_id = sqlc.arg(erased_subject_id);
